import 'dart:convert';
import 'dart:io';

import 'package:dsh_tavern/dsh_tavern.dart';
import 'package:test/test.dart';

import 'p2_script_generation_test_support.dart';
import 'spreset_engine_test.dart' show SPresetHost, preset;

void main() {
  // Generated by the actual page asset, and rechecked by its Node test. Only
  // the page boundary is substituted; DTO parsing, engine collection and the
  // public report are real. Dart tests do not require a local Node install.
  final pageResponse =
      jsonDecode(File('test/fixtures/spreset/page-console-truncation.json').readAsStringSync()) as Map<String, Object?>;

  for (final row in [
    (legacy: false, localCut: false, expected: 2),
    (legacy: false, localCut: true, expected: 3),
    (legacy: true, localCut: false, expected: 0),
  ]) {
    test('public log report counts page and Dart cuts: legacy=${row.legacy} localCut=${row.localCut}', () async {
      final h = await generationFixture();
      final host = SPresetHost();
      host.handler = (request) async {
        if (request.stage == 'EntryCondition') {
          final wire = {...pageResponse, 'requestId': request.requestId};
          if (row.legacy) wire.remove('scriptLogValuesTruncated');
          return TavernSPresetEvaluationResult.fromJson(wire);
        }
        return host.defaultEvaluate(request);
      };
      h.bridge.attachHost(host);
      final raw = preset({
        'LogUpload': {'enabled': true},
      }, stream: false).raw;
      final entry = (raw['prompts']! as List<Object?>).whereType<Map<String, Object?>>().firstWhere(
        (item) => item['identifier'] == 'fixture-slot',
      );
      entry['spreset_condition_enabled'] = true;
      entry['spreset_condition_script'] = 'synthetic-page-console';
      if (row.localCut) entry['diagnosticFixture'] = 'd' * 8193;
      await h.engine.setPreset(ChatPreset(raw));
      await h.engine.setSettings({'spresetLogUploadEnabled': true});
      final actor = await h.card('Page log report actor');
      final chat = await h.engine.createChat(actor);
      generationJsonResponse(h, {
        'choices': [
          {
            'message': {'role': 'assistant', 'content': 'done'},
            'finish_reason': 'stop',
          },
        ],
      });
      final events = await h.engine.send(chat, 'question').toList();
      expect(events.whereType<TavernTurnFailed>(), isEmpty);
      expect(events.whereType<TavernTurnDone>().single.message.text, 'done');
      final report = await h.engine.exportSPresetLogs(chat);
      final record = (report['records']! as List<Object?>).single! as Map<String, Object?>;
      expect(record['status'], 'completed');
      expect(record['scriptLogValuesTruncated'], row.expected);
      expect(record['scriptLogsDropped'], 0);
      expect(record['scriptConsoleLogsDropped'], 0);
      expect(jsonEncode(record['scriptLogs']), contains('[OMITTED string: 8193 chars]'));
      expect(jsonEncode(record['scriptLogs']), contains('[OMITTED string: 8194 chars]'));
    });
  }
}
